{
  "query": "query($id: ID!) { playlistsPorMusica(musicaId: $id) { id nome usuario { nome } } }",
  "variables": {
    "id": "{{ _.musica_id }}"
  }
}

{
  "query": "query($id: ID!) { usuario(id: $id) { id nome playlists { id nome musicas { id nome artista } } } }",
  "variables": {
    "id": "{{ _.usuario_id }}"
  }
}

{
  "query": "mutation($id: ID, $nome: String!, $idade: Int!) { criarUsuario(id: $id, nome: $nome, idade: $idade) { id nome idade } }",
  "variables": {
    "id": "{{ _.demo_usuario_id }}",
    "nome": "Aluno Demo",
    "idade": 22
  }
}

{
  "query": "mutation($id: ID!, $nome: String!, $idade: Int!) { atualizarUsuario(id: $id, nome: $nome, idade: $idade) { id nome idade } }",
  "variables": {
    "id": "{{ _.demo_usuario_id }}",
    "nome": "Aluno Demo Editado",
    "idade": 23
  }
}

{
  "query": "mutation($id: ID, $nome: String!, $artista: String!) { criarMusica(id: $id, nome: $nome, artista: $artista) { id nome artista } }",
  "variables": {
    "id": "{{ _.demo_musica_id }}",
    "nome": "Música Demo",
    "artista": "Artista Demo"
  }
}

{
  "query": "mutation($id: ID, $nome: String!, $usuarioId: ID!, $musicaIds: [ID!]) { criarPlaylist(id: $id, nome: $nome, usuarioId: $usuarioId, musicaIds: $musicaIds) { id nome usuarioId musicaIds } }",
  "variables": {
    "id": "{{ _.demo_playlist_id }}",
    "nome": "Playlist Demo",
    "usuarioId": "{{ _.usuario_id }}",
    "musicaIds": [
      "m1"
    ]
  }
}

{
  "query": "mutation($playlistId: ID!, $musicaId: ID!) { adicionarMusicaNaPlaylist(playlistId: $playlistId, musicaId: $musicaId) { id musicaIds } }",
  "variables": {
    "playlistId": "{{ _.demo_playlist_id }}",
    "musicaId": "m2"
  }
}

{
  "query": "mutation($playlistId: ID!, $musicaId: ID!) { removerMusicaDaPlaylist(playlistId: $playlistId, musicaId: $musicaId) { id musicaIds } }",
  "variables": {
    "playlistId": "{{ _.demo_playlist_id }}",
    "musicaId": "m2"
  }
}
